import{c as o,Q as t,j as s,m as a}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"a complete guide to self-improving agent systems","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-09-@aashatwt-930944.md","filePath":"research/tweets/2026-06-09-@aashatwt-930944.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-06-09-@aashatwt-930944.md"};function n(l,e,i,p,h,d){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="a-complete-guide-to-self-improving-agent-systems" tabindex="-1">a complete guide to self-improving agent systems <a class="header-anchor" href="#a-complete-guide-to-self-improving-agent-systems" aria-label="Permalink to &quot;a complete guide to self-improving agent systems&quot;">​</a></h1><p><strong>作者</strong>：aasha (@aashatwt)<br><strong>發布時間</strong>：2026-06-09<br><strong>原始連結</strong>：<a href="https://x.com/aashatwt/status/2064357944674930944" target="_blank" rel="noreferrer">https://x.com/aashatwt/status/2064357944674930944</a><br><strong>類型</strong>：Twitter Article<br><strong>統計</strong>：❤️ 103 · 🔁 7 · 🔖 115 · 👁 5,500</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Agent loop 入門概念指南：loops vs workflows（loop 根據反饋適應）、open vs closed loops、evals &gt; prompts、memory + skills 的角色；核心洞察「eval 決定 loop 有沒有用，沒有 eval = recursion not improvement」。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Loop vs Workflow 區別</strong>：workflow 跟隨預設序列；loop 根據反饋適應——prompt 問「下一步是什麼」；loop 問「完成了嗎」並持續跑到答案是 yes</li><li><strong>五個基本元素</strong>：goal / context / execution / evaluation / stopping conditions；沒有 evaluation 就沒有 loop；沒有 stopping condition 就沒有終點</li><li><strong>Evals 比 Prompts 重要（最重要洞察）</strong>： <ul><li>無 evals：agent → agent → agent = recursion（遞迴，非改進）</li><li>有 evals：agent → evaluation → feedback → agent = improvement</li><li>「evals are becoming the new prompts」</li></ul></li><li><strong>Open loop vs Closed loop</strong>：open loop 可探索新方法但成本爆炸（若 eval 弱則成為 expensive slop generator）；closed loop 有邊界，可重複，大多數 production 系統選此</li><li><strong>Memory + Skills 角色</strong>：loop 是過程；memory 是持久化（沒有 memory 每次從零開始）；skills 讓 loop 複利（solve→save→reuse 替代 solve→forget→solve）</li></ol><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>入門概念文章，深度有限——目標受眾是剛接觸 agent 的人</li><li>「evals are becoming the new prompts」是觀察入微的句子，但作者未展開如何設計 evals</li><li>Loop engineering 部分（最後）過於簡短，引出概念但未實際解釋</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>4/10</td><td>概念介紹，無具體操作指引</td></tr><tr><td>B. 創新性</td><td>5/10</td><td>eval &gt; prompt framing 有價值；其餘是已知觀念</td></tr><tr><td>C. 證據品質</td><td>4/10</td><td>個人觀察，無數據</td></tr><tr><td>D. 技術深度</td><td>4/10</td><td>入門概念，不深入</td></tr><tr><td>E. 泛化性</td><td>7/10</td><td>open vs closed loops + evals 框架普遍適用</td></tr><tr><td><strong>加權總分</strong></td><td><strong>4.65/10</strong></td><td>A×0.3 + B×0.2 + C×0.2 + D×0.15 + E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：不整合（&lt; 6 分，入門概念，無操作深度）<br><strong>整合狀態</strong>：inbox/low-score</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><h2 id="we-spent-2-years-learning-prompts-now-we-re-learning-loops" tabindex="-1">we spent 2 years learning prompts. now we&#39;re learning loops. <a class="header-anchor" href="#we-spent-2-years-learning-prompts-now-we-re-learning-loops" aria-label="Permalink to &quot;we spent 2 years learning prompts. now we&#39;re learning loops.&quot;">​</a></h2><p>you gave the agent a task - it gave you an answer. then you decided what happened next.</p><p>the agent was doing the work. you were doing the orchestration. this works for simple tasks. it breaks down the moment a task becomes iterative.</p><p>agent looping is the process of replacing yourself as the person deciding the next prompt. instead of manually steering every step, you build a system that repeatedly evaluates progress and generates the next action until a goal is reached.</p><p>a prompt is a single move. a loop is a strategy.</p><p>a prompt asks: what should happen next? a loop asks: are we done yet? and keeps running until the answer becomes yes.</p><p>at its simplest, every loop contains five parts: goal / context / execution / evaluation / stopping conditions.</p><p>without an evaluation there is no loop. without a stopping condition there is no end.</p><h2 id="workflows-vs-loops" tabindex="-1">workflows vs loops <a class="header-anchor" href="#workflows-vs-loops" aria-label="Permalink to &quot;workflows vs loops&quot;">​</a></h2><p>a workflow follows a predefined sequence. a loop adapts based on feedback. a workflow follows instructions. a loop reacts to outcomes.</p><p>that is why loops tend to perform better on messy problems where the path is unknown.</p><h2 id="open-loops-vs-closed-loops" tabindex="-1">open loops vs closed loops <a class="header-anchor" href="#open-loops-vs-closed-loops" aria-label="Permalink to &quot;open loops vs closed loops&quot;">​</a></h2><p><strong>Open loops</strong> are exploratory. The goal exists. The evaluation exists. But the path is flexible. The system can discover new approaches, create new subtasks, test multiple solutions. This is where some of the most exciting agent research is happening. It is also where costs explode. Open loops maximize discovery. But they can easily become expensive slop generators if the evaluation layer is weak.</p><p><strong>Closed loops</strong> are bounded. The agents still loop. But they loop inside a structure. They improve through repetition without wandering into nonsense. Most production systems today are closed loops. They are cheaper. More predictable. And easier to verify.</p><h2 id="why-evals-matter-more-than-prompts" tabindex="-1">why evals matter more than prompts <a class="header-anchor" href="#why-evals-matter-more-than-prompts" aria-label="Permalink to &quot;why evals matter more than prompts&quot;">​</a></h2><p>Most people think loops make agents smarter. They don&#39;t. Evals make loops useful.</p><p>Without evals: agent → agent → agent → agent. You get recursion.</p><p>With evals: agent → evaluation → feedback → agent. You get improvement.</p><p>The evaluation layer decides whether the output is acceptable, whether another iteration is needed, whether the system should stop.</p><p>In many ways, evals are becoming the new prompts.</p><h2 id="where-memory-fits" tabindex="-1">where memory fits <a class="header-anchor" href="#where-memory-fits" aria-label="Permalink to &quot;where memory fits&quot;">​</a></h2><p>A loop is the process. Memory is persistence. Without memory, every run starts from zero. With memory, the system accumulates knowledge over time.</p><p>Memory can be: markdown files / databases / linear boards / vector stores / knowledge graphs. The implementation changes. The principle stays the same. The agent forgets. The system remembers. Memory is what allows loops to survive beyond a single conversation.</p><h2 id="skills-are-where-loops-compound" tabindex="-1">skills are where loops compound <a class="header-anchor" href="#skills-are-where-loops-compound" aria-label="Permalink to &quot;skills are where loops compound&quot;">​</a></h2><p>A loop without skills has to rediscover everything every run. A loop with skills gets stronger over time. A skill is simply reusable knowledge.</p><p>Without skills: solve → forget → solve → forget → solve. With skills: solve → save → reuse forever.</p><p>This is how loops start compounding instead of just consuming tokens.</p><h2 id="what-is-loop-engineering" tabindex="-1">what is loop engineering? <a class="header-anchor" href="#what-is-loop-engineering" aria-label="Permalink to &quot;what is loop engineering?&quot;">​</a></h2><p>Agent looping is the mechanism. Loop engineering is the discipline. You are no longer programming the agent directly. You are programming the environment around it.</p><p>The leverage point moves from: what prompt should I write? to: what system should I build?</p><p>The biggest challenge: cost. Loops are expensive. A loop without guardrails can burn tokens indefinitely.</p><p>we spent the last two years learning how to talk to agents. the next few years will be spent learning how to build systems that talk to them for us.</p>',47)])])}const c=o(r,[["render",n]]);export{m as __pageData,c as default};
